import{d as r,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十五章","description":"《正易心法》第二十五章——中爻之义，足为造化：以纳音与反切为喻，说明中爻（二三四五）是乾坤交错、造化化生的场所；参互成卦，故一卦具于四卦中，皆得祸福倚伏之象。","frontmatter":{"title":"正易心法·第二十五章","description":"《正易心法》第二十五章——中爻之义，足为造化：以纳音与反切为喻，说明中爻（二三四五）是乾坤交错、造化化生的场所；参互成卦，故一卦具于四卦中，皆得祸福倚伏之象。","category":"guide","aliases":["正易心法第二十五章","中爻之义足为造化","参互成卦"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-25.md","filePath":"yijing/zheng-yi-xin-fa/chapter-25.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-25.md"},k=r({...c,setup(u){const i=[{id:"z25-01",label:"一、中爻足为造化",showLabel:!0,sentences:[[{text:"中爻",glossary:"zhongyao"},"之义，足为",{text:"造化",glossary:"zaohua"},"。纳音为",{text:"切脚",glossary:"qiejiao"},"，其理则一。"]],note:["中爻的意义，足以成为造化的枢纽。纳音与反切注音，道理是同一个。（**「中爻」指二、三、四、五爻**——除初爻、上爻之外的四爻，也就是两个互体的取爻范围。**本章是第十九章「互卦」的进一步深化**：第十九章说一卦含八卦，本章说中爻就是那「造化之气」发生的地方。）"]},{id:"z25-02",label:"二、纳音之喻",showLabel:!0,sentences:[["纳音，甲为木，子为水，甲子交合则生金。"]],note:["纳音：甲属木，子属水，甲子两者交合，纳音则生金。（**两个已知元素交合，生出第三个新元素**——这是「造化」的最小模型：**两端相交，中间生新。** 甲子纳音为「海中金」，是六十甲子纳音的起首。）"]},{id:"z25-03",label:"三、切脚之喻",showLabel:!0,sentences:[["切脚，如德为父，红为母，德红反切即东字。"]],note:["反切：比如「德」为父（取声母），「红」为母（取韵母），德红反切，就拼出「东」字的读音。（**上字取声、下字取韵，两字合成一个新字**——与纳音、与卦画是同一个道理：**两端相合，生出第三者。**「切脚」即「反切」，古代的注音法。）"]},{id:"z25-04",label:"四、卦体亦然",showLabel:!0,sentences:[["卦体亦然。上体为乾，下体为坤，交错乃生六子，即中爻二三四五也。"]],note:["卦的结构也是如此：上体为乾、下体为坤，两者交错乃生六子——这就是中爻的二、三、四、五爻。（**第三个类比**：乾坤（父母）交合 → 六子（中爻）。**造化的本质是：阴阳（两端）交合，在中间生出新的存在。** 这与第九章「乾坤错杂，乃生六子」是同一件事，本章给出了它的普遍形式。）"]},{id:"z25-05",label:"五、参互成卦",showLabel:!0,sentences:[["二三四五，造化之气，",{text:"参互成卦",glossary:"canhuChengua"},"。"]],note:["二、三、四、五爻，是造化之气，相互交叉参合，组成新的卦象。（**从中爻取互卦**：上互取三、四、五爻，下互取二、三、四爻，两个互体合成一个新的六爻卦——这就是第十九章所说的「参卦」。**麻衣强调的不是机械推算，而是每一卦的内部都藏着别的卦。**）"]},{id:"z25-06",label:"六、祸福倚伏",showLabel:!0,sentences:[["如屯中有剥，蒙中有复，主此一卦每具于四卦中，皆得",{text:"祸福倚伏",glossary:"huofuYifu"},"之象。如屯、比、观、益中皆有剥，蒙、师、损中皆有复是也。"]],note:["比如屯卦中含有剥卦，蒙卦中含有复卦——这说明每一卦都具备于另外四卦之中，都能得到祸福倚伏的卦象。就像屯、比、观、益中都含有剥，蒙、师、损中都含有复。（**「祸福倚伏」语出《老子》「祸兮福所倚，福兮祸所伏」**——吉卦（益）中藏着凶卦（剥），凶卦（屯）中也藏着凶卦（剥）：**祸福从不单独存在，任何当下状态都同时包含着其他卦的潜在走向。**）"]}],o=[{id:"zhongyao",term:"中爻",pinyin:"zhōng yáo",meaning:"六爻卦中的二、三、四、五爻（除初、上之外的四爻），是造化之气的所在。"},{id:"zaohua",term:"造化",pinyin:"zào huà",meaning:"天地化生万物的功能。「足为造化」即足以成为造化的枢纽。"},{id:"qiejiao",term:"切脚",pinyin:"qiè jiǎo",meaning:"即「反切」，古代的注音法：取上字声母、下字韵母拼合成新字的读音。"},{id:"canhuChengua",term:"参互成卦",pinyin:"cān hù chéng guà",meaning:"中爻二三四五相互交叉参合，组成新的卦象（即互体与参卦）。"},{id:"huofuYifu",term:"祸福倚伏",pinyin:"huò fú yǐ fú",meaning:"祸福相互依存、隐伏。语出《老子》「祸兮福所倚，福兮祸所伏」。"}];return(b,n)=>{const l=s("DaoTextReading"),p=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",23)),e(l,{colophon:"中爻造化 · 纳音切脚 · 参互成卦 · 祸福倚伏",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十五章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。标题句「纳音为切脚」之「为」，据文义当读作「与／如」（纳音与反切），仍依底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"中爻",pinyin:["zhōng","yáo"],meaning:"二、三、四、五爻（除初、上之外的四爻）——是造化之气的所在，互体与参卦的取爻范围。"},{term:"纳音",pinyin:["nà","yīn"],meaning:"甲（木）与子（水）交合而生金——两个已知元素交合，生出第三个新元素。"},{term:"切脚（反切）",pinyin:["qiè","jiǎo"],meaning:"「德」取声母、「红」取韵母，合成「东」——上字取声、下字取韵，两字生一新字。"},{term:"参互成卦",pinyin:["cān","hù"],meaning:"中爻二三四五相互交叉参合组成新卦。麻衣的重点不在机械推算，而在一卦内部藏着别的卦。"},{term:"祸福倚伏",pinyin:["huò","fú"],meaning:"《老子》「祸兮福所倚，福兮祸所伏」。屯中有剥、蒙中有复——祸福从不单独存在。"}]}),n[3]||(n[3]=t("",24))])}}});export{y as __pageData,k as default};
